-- =============================================================
-- 词库补导补丁：dict_cet.sql（6662 词）+ dict_word_basic.sql（101 词）
-- 以 INSERT IGNORE 补进库：只补缺失的词，不覆盖已修复的存量数据
-- 并回填 level（四级/六级）与 is_core（高频核心词）标记，可重复执行
-- 用法：DBeaver 打开本文件（确认编码 UTF-8），Alt+X 执行整个脚本
-- =============================================================
USE `word_spirit`;
-- 按 difficulty 回填 level（新补的词默认 other，需要回填 cet4/cet6）
UPDATE `dict_word` SET `level` = 'cet4' WHERE `difficulty` = 2 AND `level` = 'other';
UPDATE `dict_word` SET `level` = 'cet6' WHERE `difficulty` = 4 AND `level` = 'other';

-- 词灵学园 四六级完整词库（来源：KyleBing/english-vocabulary，CC BY 4.0）
-- CET4 难度=2，CET6 难度=4；按单词去重；幂等导入（ON DUPLICATE KEY UPDATE）
ON DUPLICATE KEY UPDATE phonetic=VALUES(phonetic),pos=VALUES(pos),meaning=VALUES(meaning),example=VALUES(example),example_cn=VALUES(example_cn),difficulty=VALUES(difficulty);
ON DUPLICATE KEY UPDATE phonetic=VALUES(phonetic),pos=VALUES(pos),meaning=VALUES(meaning),example=VALUES(example),example_cn=VALUES(example_cn),difficulty=VALUES(difficulty);
